1	export type QuoteResult = {
2	  premium: number;
3	};
4	
5	export type ClaimResult = {
6	  payout: number;
7	  remainingCap: number;
8	};
9	
10	export type StepResult = QuoteResult | ClaimResult;
11	
12	export type ScenarioOutcome = {
13	  results: StepResult[];
14	};
15	
16	type Item = { type: string; cursed?: boolean; enchantment?: number };
17	
18	type Customer = { yearsWithMHPCO: number };
19	
20	/** The policy-scope context a quote is priced in: who is buying, and whether
21	 * this is their first contract or a follow-up. */
22	type Policy = { customer: Customer; isFollowUpContract: boolean };
23	
24	type Damage = { itemType: string; amount: number };
25	
26	type Incident = { cause: string; damages: Damage[] };
27	
28	type QuoteStep = { op: string; items: Item[] };
29	
30	type ClaimStep = { op: string; policy: number; incident: Incident };
31	
32	type Step = QuoteStep | ClaimStep;
33	
34	const isQuoteStep = (step: Step): step is QuoteStep => step.op === "quote";
35	
36	type Scenario = {
37	  customer: Customer;
38	  steps: Step[];
39	};
40	
41	const PROCESSING_FEE = 5;
42	const FIRST_INSURANCE_SURCHARGE = 0.1;
43	const CURSE_SURCHARGE = 0.5;
44	const HIGH_ENCHANTMENT_THRESHOLD = 5;
45	const HIGH_ENCHANTMENT_SURCHARGE = 0.3;
46	const LOYALTY_THRESHOLD_YEARS = 2;
47	const LOYALTY_DISCOUNT = 0.2;
48	const FOLLOW_UP_CONTRACT_DISCOUNT = 0.15;
49	
50	const BASE_PREMIUMS: Record<string, number> = {
51	  sword: 100,
52	  amulet: 60,
53	  staff: 80,
54	  potion: 40,
55	  rune: 25,
56	  moonstone: 25,
57	};
58	
59	const INSURANCE_VALUES: Record<string, number> = {
60	  sword: 1000,
61	  rune: 250,
62	};
63	
64	const DEDUCTIBLE_PER_DAMAGE = 100;
65	const CAP_MULTIPLIER = 2;
66	
67	const ALIKE_BLOCK_SIZE = 3;
68	const ALIKE_BLOCK_PREMIUM = 60;
69	
70	type AlikeGroup = [type: string, count: number];
71	
72	const groupAlikeItems = (items: Item[]): AlikeGroup[] => {
73	  const countByType = new Map<string, number>();
74	
75	  for (const item of items) {
76	    countByType.set(item.type, (countByType.get(item.type) ?? 0) + 1);
77	  }
78	
79	  return [...countByType];
80	};
81	
82	const basePremiumOfType = (type: string): number => BASE_PREMIUMS[type];
83	
84	const ownBasePremiumOf = (item: Item): number => basePremiumOfType(item.type);
85	
86	const basePremiumOfGroup = ([type, count]: AlikeGroup): number => {
87	  if (count === ALIKE_BLOCK_SIZE) return ALIKE_BLOCK_PREMIUM;
88	
89	  return count * basePremiumOfType(type);
90	};
91	
92	/**
93	 * The policy base premium: the sum of the item base premiums, with the
94	 * alike-block discount applied. Policy-scope modifiers are percentages OF
95	 * THIS amount — never of a total that already includes item surcharges.
96	 */
97	const policyBasePremiumOf = (items: Item[]): number =>
98	  groupAlikeItems(items)
99	    .map(basePremiumOfGroup)
100	    .reduce((total, groupPremium) => total + groupPremium, 0);
101	
102	/**
103	 * Item-scope surcharges: each is a percentage of the affected item's OWN base
104	 * premium, independent of the policy base and of the alike-block discount.
105	 */
106	const isCursed = (item: Item): boolean => item.cursed === true;
107	
108	const isHighlyEnchanted = (item: Item): boolean =>
109	  (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_THRESHOLD;
110	
111	const itemSurchargeRateOf = (item: Item): number =>
112	  (isCursed(item) ? CURSE_SURCHARGE : 0) +
113	  (isHighlyEnchanted(item) ? HIGH_ENCHANTMENT_SURCHARGE : 0);
114	
115	const itemSurchargesOf = (items: Item[]): number =>
116	  items.reduce(
117	    (total, item) => total + ownBasePremiumOf(item) * itemSurchargeRateOf(item),
118	    0,
119	  );
120	
121	/**
122	 * Policy-scope modifiers: each is a percentage of the policy base premium.
123	 * Surcharges and discounts are netted into a single rate, so the policy base is
124	 * multiplied exactly once — this keeps the result free of the rounding drift
125	 * that separate discount and surcharge terms would introduce. The netted rate
126	 * (and hence the returned amount) is negative when the discounts outweigh the
127	 * surcharges.
128	 */
129	const isLongStanding = (customer: Customer): boolean =>
130	  customer.yearsWithMHPCO >= LOYALTY_THRESHOLD_YEARS;
131	
132	const policyModifierRateOf = ({ customer, isFollowUpContract }: Policy): number =>
133	  FIRST_INSURANCE_SURCHARGE -
134	  (isLongStanding(customer) ? LOYALTY_DISCOUNT : 0) -
135	  (isFollowUpContract ? FOLLOW_UP_CONTRACT_DISCOUNT : 0);
136	
137	const policyModifiersOn = (policyBase: number, policy: Policy): number =>
138	  policyBase * policyModifierRateOf(policy);
139	
140	const quotePremium = (items: Item[], policy: Policy): number => {
141	  const policyBase = policyBasePremiumOf(items);
142	  const premium =
143	    policyBase +
144	    itemSurchargesOf(items) +
145	    policyModifiersOn(policyBase, policy) +
146	    PROCESSING_FEE;
147	
148	  return Math.ceil(premium);
149	};
150	
151	/**
152	 * Whether any step precedes this one. A quote is a follow-up contract when the
153	 * customer already holds one, and today every step is a quote — so "has a
154	 * predecessor" and "is a follow-up contract" coincide.
155	 *
156	 * They stop coinciding once claim steps exist: a claim at index 0 would make
157	 * the quote at index 1 look like a follow-up. At that point the caller must
158	 * count preceding QUOTE steps instead of asking this. The name is deliberately
159	 * about position, not contracts, so that the substitution is a visible change
160	 * at the call site rather than a silent redefinition here.
161	 */
162	const hasPrecedingStep = (stepIndex: number): boolean => stepIndex > 0;
163	
164	const insuranceSumOf = (items: Item[]): number =>
165	  items.reduce((sum, item) => sum + INSURANCE_VALUES[item.type], 0);
166	
167	const payoutForDamage = (damage: Damage): number =>
168	  damage.amount - DEDUCTIBLE_PER_DAMAGE;
169	
170	/**
171	 * The quote step a claim is filed against. Today this ASSUMES the referenced
172	 * index holds a quote: nothing has forced the assumption to be checked yet, and
173	 * a claim naming a non-quote step fails here with an opaque undefined-property
174	 * error rather than a rejection.
175	 *
176	 * The assumption is isolated in this function on purpose. The pending
177	 * error-handling tests ("a claim for an item not part of the policy", "a claim
178	 * with a damage entry of an unknown item type") are what will force a real
179	 * rejection, and this is the single place that has to change when they do.
180	 */
181	const policyReferencedBy = (claim: ClaimStep, steps: Step[]): QuoteStep =>
182	  steps[claim.policy] as QuoteStep;
183	
184	const settleClaim = (claim: ClaimStep, steps: Step[]): ClaimResult => {
185	  const policy = policyReferencedBy(claim, steps);
186	  const cap = CAP_MULTIPLIER * insuranceSumOf(policy.items);
187	  const payout = claim.incident.damages.reduce(
188	    (total, damage) => total + payoutForDamage(damage),
189	    0,
190	  );
191	
192	  return { payout, remainingCap: cap - payout };
193	};
194	
195	export const runScenario = (scenario: Scenario): ScenarioOutcome => ({
196	  results: scenario.steps.map((step, stepIndex) =>
197	    isQuoteStep(step)
198	      ? {
199	          premium: quotePremium(step.items, {
200	            customer: scenario.customer,
201	            isFollowUpContract: hasPrecedingStep(stepIndex),
202	          }),
203	        }
204	      : settleClaim(step, scenario.steps),
205	  ),
206	});
